{
  "root_causes": [
    {
      "service": "user",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {"kind": "metric", "sql": "SELECT time, attr_k8s_pod_name, metric, value FROM abnormal_metrics WHERE metric = 'k8s.container.ready' AND attr_k8s_pod_name LIKE 'user-%' ORDER BY time", "claim": "The user pod reports k8s.container.ready=0 for every abnormal sample, versus 1 in normal."},
        {"kind": "trace", "sql": "SELECT span_name, attr_status_code, count(*) n, round(avg(duration)/1e6,2) avg_ms FROM abnormal_traces WHERE span_name = 'user.User/CheckUser' GROUP BY ALL", "claim": "All 200 frontend calls to user.User/CheckUser fail with Error in about 0.02 ms; no user server spans exist."},
        {"kind": "log", "sql": "SELECT service_name, level, message, count(*) n FROM abnormal_logs WHERE level = 'ERROR' GROUP BY ALL", "claim": "Frontend logs 34 ERROR entries 'User authentication failed' during the incident window."}
      ]
    },
    {
      "service": "attractions",
      "fault_kind": "container_memory_saturated",
      "evidence": [
        {"kind": "metric", "sql": "SELECT date_trunc('minute', time) m, round(max(value)/1e6,1) rss_mb FROM abnormal_metrics WHERE service_name = 'attractions' AND metric = 'container.memory.rss' GROUP BY 1 ORDER BY 1", "claim": "Attractions container RSS jumps from about 25 MB to about 772 MB in the first abnormal minute and stays there."},
        {"kind": "metric", "sql": "SELECT metric, round(avg(value),3) avg_v FROM abnormal_metrics WHERE service_name = 'attractions' AND metric = 'container.cpu.usage' GROUP BY 1", "claim": "Attractions CPU usage is essentially zero during the abnormal window while memory is pinned high."},
        {"kind": "trace", "sql": "SELECT 'normal' p, service_name, count(*) n FROM normal_traces WHERE service_name = 'attractions' GROUP BY 1,2 UNION ALL SELECT 'abnormal', service_name, count(*) FROM abnormal_traces WHERE service_name = 'attractions' GROUP BY 1,2", "claim": "Attractions emits 521 spans in normal period and zero spans in the abnormal period."},
        {"kind": "trace", "sql": "SELECT span_name, count(*) n FROM normal_traces WHERE service_name = 'frontend' AND span_name LIKE 'attractions.%' GROUP BY 1 UNION ALL SELECT span_name, count(*) FROM abnormal_traces WHERE service_name = 'frontend' AND span_name LIKE 'attractions.%' GROUP BY 1", "claim": "Frontend's NearbyCinema, NearbyMus and NearbyRest calls to attractions occur in normal period but never appear in the abnormal period."}
      ]
    }
  ],
  "propagation": [
    {
      "from": "user",
      "to": "frontend",
      "evidence": [
        {"kind": "trace", "sql": "SELECT span_name, attr_span_kind, attr_http_response_status_code code, count(*) n, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces WHERE service_name = 'frontend' AND (span_name = 'user.User/CheckUser' OR span_name = 'HTTP /user') GROUP BY ALL", "claim": "Frontend's CheckUser client calls and its HTTP /user server spans all end in Error status."}
      ]
    },
    {
      "from": "attractions",
      "to": "frontend",
      "evidence": [
        {"kind": "trace", "sql": "SELECT span_name, attr_http_response_status_code code, count(*) n, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces WHERE service_name = 'frontend' AND attr_span_kind = 'Server' AND span_name IN ('HTTP /cinema','HTTP /museums','HTTP /restaurants') GROUP BY ALL", "claim": "Frontend /cinema, /museums and /restaurants server spans return HTTP 500 with Error status in the abnormal period."}
      ]
    }
  ]
}

